import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第三册：培养技能 · Lesson 12 Life on a desert island","description":"学习 第二条件句的假设距离，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 12 Life on a desert island","description":"学习 第二条件句的假设距离，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 第二条件句的假设距离，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 11 Not guilty","link":"/life/english/new-concept/book-3/unit-01/lesson-011"},"next":{"text":"第三册：培养技能 · Lesson 13 It's only me","link":"/life/english/new-concept/book-3/unit-01/lesson-013"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 11 Not guilty","link":"/life/english/new-concept/book-3/unit-01/lesson-011"},"next":{"text":"第三册：培养技能 · Lesson 13 It's only me","link":"/life/english/new-concept/book-3/unit-01/lesson-013"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-012.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-012.md"}`),i={name:"life/english/new-concept/book-3/unit-01/lesson-012.md"};function l(r,e,s,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-12-life-on-a-desert-island" tabindex="-1">第三册：培养技能 · Lesson 12 Life on a desert island <a class="header-anchor" href="#第三册-培养技能-·-lesson-12-life-on-a-desert-island" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 12 Life on a desert island&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从远离日常生活的想象转向具体生存条件，练习讨论非现实情境中的选择。不要只写“生活很好”之类结论，要说明水、食物和通信等条件如何影响判断。学习第二条件句表达当前或未来不太现实的假设，同时区分建议与真实计划。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>resource</td><td>/rɪˈzɔːs/</td><td>n.</td><td>资源</td><td>limited resources</td></tr><tr><td>supply</td><td>/səˈplaɪ/</td><td>n.</td><td>补给</td><td>a water supply</td></tr><tr><td>isolation</td><td>/ˌaɪsəˈleɪʃən/</td><td>n.</td><td>隔绝</td><td>live in isolation</td></tr><tr><td>shelter</td><td>/ˈʃeltə/</td><td>v.</td><td>躲避风雨</td><td>shelter from rain</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>do without — 没有某物也设法生活或完成任务</li><li>depend on — 依赖某资源或条件</li></ul><h2 id="语法讲解-第二条件句的假设距离" tabindex="-1">语法讲解：第二条件句的假设距离 <a class="header-anchor" href="#语法讲解-第二条件句的假设距离" aria-label="Permalink to &quot;语法讲解：第二条件句的假设距离&quot;">​</a></h2><p>if 从句用一般过去式，主句用 would、could 或 might 加动词原形，可以表达现在或将来的非现实、低可能假设。这里的过去式主要表示假设距离，不一定表示过去时间。正式表达中 If I were ... 常见；口语中的 was 也可出现，但练习统一用 were 便于识别结构。若情境真实且有实现可能，可用第一条件句。第二条件句并非预测概率的数学工具，语气仍取决于说话人的立场与上下文。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If I lived on a remote island, I would choose a reliable radio over a television.</p></blockquote><p>如果我住在偏远岛屿上，我会选可靠的收音通信设备，而不是电视。</p><p>lived 表假设而非实际过去；would choose 是设想的选择；over 表示优先于。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>If I would live there 混淆条件与结果；通常写 If I lived there, I would ...。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 If I stayed 与 I would bring 分成两个语调组；录音后检查 would 是否听得见，避免听成既定计划。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>If I stayed in a remote cabin, I would bring a radio. It could help me receive weather warnings. I would still need a safe way to leave in an emergency.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为独处一周的虚构情境列出一个优先物品、一个理由和一个限制。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>所有选择围绕具体需求，最后一句补足单一工具无法解决的限制。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句中的 lived 是否说明说话者以前住过岛上？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> 过去式用于表达假设距离。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：If I ___ you, I would carry extra water.（were/am）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 这是非现实建议结构。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 would choose 改成表示“可能选择”。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> might choose</p><p><strong>解析：</strong> might 降低结果的确定性。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：第二条件句的假设距离。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-011">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-013">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(i,[["render",l]]);export{p as __pageData,f as default};
